from typing import List

def remove_duplicates(numbers: List[int]) -> List[int]:
    # Create a dictionary to count occurrences of each number
    count_dict = {}
    for num in numbers:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    # Use a list comprehension to filter out numbers that appear more than once
    return [num for num in numbers if count_dict[num] == 1]
