def decode_shift(s: str) -> str:
    """
    Encodes and decodes strings by shifting each character by 5 positions in the alphabet.

    Parameters:
    s (str): The string to be encoded or decoded.

    Returns:
    str: The encoded or decoded string.
    """
    def shift_char(c: str, shift: int) -> str:
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + shift) % 26 + ord('A'))
        else:
            return c

    # Decode the string by shifting each character by -5 positions
    return ''.join(shift_char(c, -5) for c in s)
```

