def split_words(txt):
    # Check if the string contains spaces
    if ' ' in txt:
        return txt.split(' ')
    # Check if the string contains commas
    elif ',' in txt:
        # Replace commas with spaces and split the string
        return txt.replace(',', ' ').split()
    else:
        # Count the number of lowercase letters with ASCII values less than 100
        return [char for char in txt if char.islower() and ord(char) < 100]
