def is_nested(string):
    # Initialize counters for open and close brackets
    open_bracket_count = 0
    close_bracket_count = 0

    # Iterate through the string to count open and close brackets
    for char in string:
        if char == '[':
            open_bracket_count += 1
        elif char == ']':
            close_bracket_count += 1

    # Check if there are at least two pairs of nested brackets
    if open_bracket_count > 0 and close_bracket_count > 0 and open_bracket_count >= close_bracket_count:
        return True
    else:
        return False
